paginas.codigo:
.pagina {
  display: grid;
  grid-template-areas:
    "cabecera"
    "menu"
    "contenido"
    "pie";
}

@media (min-width: 768px) {
  .pagina {
    grid-template-columns: 200px 1fr;
    grid-template-areas:
      "cabecera cabecera"
      "menu     contenido"
      "pie      pie";
  }
}

.tarjetas {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
}

h1 {
  font-size: clamp(1.5rem, 4vw, 3rem);
}

img {
  max-width: 100%;
  height: auto;
}
